def replace_references(roots):
    """Opt in existing dispatch calls on a disposable candidate graph."""
    from . import curved_separator_dispatch_nodes as dispatch
    pending=list(roots);seen=set();originals=[]
    while pending:
        tree=pending.pop()
        if tree.as_pointer() in seen:continue
        seen.add(tree.as_pointer())
        pending.extend(n.node_tree for n in tree.nodes if n.type=='GROUP' and n.node_tree)
        if tree.name.startswith(dispatch.NAME) and not tree.get('st_batched_free_candidate'):
            originals.append(tree)
    if not originals:raise ValueError('No declared separator dispatch to replace')
    rows=[]
    for original in originals:
        flags={key:token in original.name for key,token in (
            ('retain_failures',' / Retain valid surfaces'),('chained',' / Chained separators v1'),
            ('free_chains',' / Free chained separators v1'),('regions',' / Crossing regions v1'))}
        expected=dispatch.NAME+(' / Retain valid surfaces' if flags['retain_failures'] else '')
        revision=original.get('st_longitudinal_separator_chains',0)
        if revision not in (0,1):raise ValueError('Unknown longitudinal dispatch revision')
        flags['longitudinal_chains']=bool(revision) or ' / Original terminal owner rows v1' in original.name
        for key,token in (('chained',' / Chained separators v1'),('free_chains',' / Free chained separators v1'),
                          ('longitudinal_chains',' / Original terminal owner rows v1'),('regions',' / Crossing regions v1')):
            if key=='longitudinal_chains' and token not in original.name:continue
            if flags[key]:expected+=token
        if original.name!=expected:raise ValueError('Unknown dispatch revision: '+original.name)
        replacement=dispatch.build(**flags,batch_free=True)
        schema=lambda g:[(s.name,s.in_out,s.socket_type) for s in g.interface.items_tree if s.item_type=='SOCKET']
        if schema(original)!=schema(replacement):raise ValueError('Dispatch interface changed')
        replacement['st_batched_free_candidate']=True
        original.user_remap(replacement)
        rows.append(dict(previous=original.name,candidate=replacement.name,**flags))
    return rows


